data.query:
query ProductionSetupOutput($filter: ProductionSetupOutputWhereInput, $orderBy: [ProductionSetupOutputOrderByInput!], $first: Int, $after: String, $readPreference: ReadPreferenceEnum) {
  outputs: productionSetupOutput(where: $filter, orderBy: $orderBy, first: $first, after: $after, readPreference: $readPreference) {
    total
    edges {
      node {
        id
        workcenterId
        workOrder {
          number
          productStrategy {
            certification
          }
        }
        product {
          code
          certification
        }
        productId
        workOrderProcess {
          process {
            code
            certification
          }
          order
        }
        workOrderDistributionGroupId
        productStrategyProcessId
        productStrategyProcess {
          id
          certification
          processId
          productStrategyId
        }
        distributionQuantity
        producedQuantity
        scrappedQuantity
      }
    }
  }
}

query Query($filter: CertificationRequirementWhereInput) {
  certificationRequirement(where: $filter){
    edges{
      node{
        id
        name
      }
    }
  }
}

query ($workcenterId: String, $certificationRequirements: [String!]!, $now: Date) {
  productionSetupOperator(where: {workcenterId: {_eq: $workcenterId}}) {
    edges {
      node {
        id
        employee {
          id
          employeeCertifications(where: {certificationId: {_in: $certificationRequirements}, active: {_eq: true}, _and: [{_or: [{effectiveAt: {_lte: $now}}, {effectiveAt: {_isNull: true}}]}, {_or: [{expirationAt: {_gt: $now}}, {expirationAt: {_isNull: true}}]}]}) {
            edges {
              node {
                id
                certificationId
              }
            }
          }
        }
      }
    }
  }
}

data.responseTransform:
{
  "success": false,
  "message": "Not all operators are certified for every requirment."
}

